"""Build source-grounded checklists, detailed answers and executable transfer exercises."""
import json,re,hashlib,subprocess,sys,sqlite3
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
cards=json.loads((ROOT/'android/app/src/main/assets/cards.json').read_text())['cards']
source=(ROOT/'android/app/src/main/java/com/python/interviewcards/LearningHints.kt').read_text().split('fun mistake')[0]
analogies=dict(re.findall(r'"(\d{2})"->"([^"\n]+)"',source));tracks=[]
def track(text,kind,parts=None):
 key=hashlib.sha256(text.encode()).hexdigest()[:20];path=f'audio/v5_{kind}_{key}.mp3';tracks.append(dict(id=key,text=text,path=path,parts=parts));return path
def py(n):return f'py-middle-{n:03}'
prepared={}
understanding=json.loads((ROOT/'audio/understanding-manifest.json').read_text())['files']
for c in cards:
 parts=re.split(r'(?<=[.!?])\s+(?=[А-ЯA-ZЁ0-9])',c['answer'])
 if len(parts)>3:parts=parts[:2]+[' '.join(parts[2:])]
 points=parts+['Объяснить пример: '+c['example_note']]
 if len(points)<3:points+=['Ответить на уточнение: '+c['self_check']]
 assert 3<=len(points)<=5
 detailed='Подробный ответ. '+c['answer']+' Простыми словами. '+(c.get('plain_explanation') or c['example_note'])+' Аналогия. '+(c.get('analogy') or analogies[c['category_id']])+' Разберём пример. '+c['example_note']
 parts=None
 if not c.get('plain_explanation') or c['plain_explanation']==c['example_note']:
  # Existing explanation already explains the example. Keep it once, with the exact recorded wording.
  detailed=c['answer']+'\n\n'+understanding[Path(c['explanation_audio']).name]['source_text']+'\n\n'+understanding[Path(c['analogy_audio']).name]['source_text']
  parts=[c['answer_audio'],c['explanation_audio'],c['analogy_audio']]
 prepared[c['id']]=dict(checklist=points,short=c['answer'],short_audio=c['answer_audio'],detailed=detailed,detailed_audio=track(detailed,'detail',parts))
# Every executable result below is computed independently, then stored with an explanation.
whatifs=[]
def exercise(title,base,change,code,explanation,card,kind='python'):
 if kind=='python':
  r=subprocess.run([sys.executable,'-I','-c',code],capture_output=True,text=True,timeout=4,check=True);answer=r.stdout.rstrip()
 else:
  db=sqlite3.connect(':memory:');db.executescript('CREATE TABLE users(id INTEGER, name TEXT); INSERT INTO users VALUES(1,"Анна"),(2,"Борис"); CREATE TABLE orders(id INTEGER,user_id INTEGER,amount INTEGER); INSERT INTO orders VALUES(10,1,100),(11,1,NULL);')
  answer='\n'.join(' | '.join('NULL' if v is None else str(v) for v in row) for row in db.execute(code));db.close()
 item=dict(id=f'whatif-{len(whatifs)+1:03}',title=title,base=base,change=change,code=code,answer=answer,explanation=explanation,card_id=card,kind=kind)
 item['audio']=track(title+'. Изменение условия. '+change+' Результат. '+answer.replace('\n','; ')+' Объяснение. '+explanation,'whatif');whatifs.append(item)
exercise('Копия внешнего списка','b = a связывает два имени с одним списком.','Заменили присваивание на срез. Что изменится в a?', 'a = [1, 2]\nb = a[:]\nb.append(3)\nprint(a)', 'Срез создаёт новый внешний список. Добавление элемента в b не изменяет a.',py(27))
exercise('Вложенный объект остался общим','Срез создал новый внешний список.','Вместо добавления элемента меняем вложенный список.', 'a = [[1], [2]]\nb = a[:]\nb[0].append(9)\nprint(a)', 'Поверхностная копия разделяет вложенные объекты. a[0] и b[0] ссылаются на один список.',py(27))
exercise('Глубокая копия','Поверхностная копия разделяла вложенные списки.','Используем deepcopy перед изменением вложенного списка.', 'from copy import deepcopy\na = [[1], [2]]\nb = deepcopy(a)\nb[0].append(9)\nprint(a)', 'Для этого примера deepcopy создаёт отдельные вложенные списки, поэтому исходная структура не меняется.',py(27))
exercise('Создать генератор снова','Исчерпанный генератор повторно не выдаёт значения.','Перед вторым проходом создаём новый генератор.', 'g = (x * 2 for x in range(3))\nprint(list(g))\ng = (x * 2 for x in range(3))\nprint(list(g))', 'Новый объект генератора имеет собственное состояние обхода; второй список не пуст.',py(25))
exercise('Сохранить поток в список','Один генератор расходуется при обходе.','Один раз материализуем значения, затем обходим список дважды.', 'values = list(x * 2 for x in range(3))\nprint(sum(values))\nprint(sum(values))', 'Список допускает повторные обходы, но хранит все значения в памяти.',py(26))
exercise('Значение по умолчанию None','Изменяемый аргумент по умолчанию сохраняется между вызовами.','Создаём новый список внутри функции при None.', 'def add(x, items=None):\n    if items is None:\n        items = []\n    items.append(x)\n    return items\nprint(add(1))\nprint(add(2))', 'В каждом таком вызове создаётся отдельный список; явный переданный список всё ещё может изменяться.',py(4))
exercise('Зафиксировать значение замыкания','Lambda в цикле читала текущее значение общей переменной.','Запоминаем значение в параметре по умолчанию.', 'fs = [lambda i=i: i for i in range(3)]\nprint([f() for f in fs])', 'Значения параметров по умолчанию вычисляются при создании каждой функции.',py(31))
exercise('Независимые строки матрицы','Умножение списка повторяет ссылки на одну строку.','Строки создаются включением.', 'm = [[0] * 2 for _ in range(3)]\nm[0][0] = 7\nprint(m)', 'Каждая итерация создаёт новый внутренний список; изменяется одна строка.',py(28))
exercise('Порядок после повторной вставки','Обновление значения существующего ключа не меняет его позицию.','Сначала удаляем ключ, потом вставляем снова.', 'd = {"a": 1, "b": 2}\nd.pop("a")\nd["a"] = 3\nprint(list(d))', 'Новая вставка удалённого ключа ставит его в конец порядка вставки.',py(13))
exercise('Пустые any и all','any и all проверяют истинность элементов.','На входе нет элементов.', 'print(any([]))\nprint(all([]))', 'Для any не найден истинный элемент: False. Для all не найден ложный элемент: True.',py(29))
exercise('Возврат из finally','try уже подготовил возвращаемое значение.','В finally добавлен свой return.', 'def f():\n    try:\n        return 1\n    finally:\n        return 2\nprint(f())', 'Возврат из finally заменяет подготовленный результат; такая конструкция также может подавлять исключение и обычно нежелательна.',py(10))
exercise('Сравнение разных объектов','Два списка содержат одинаковые значения.','Один список создаём копированием, а не присваиванием.', 'a = [1]\nb = a.copy()\nprint(a == b)\nprint(a is b)', 'Равенство содержимого истинно, идентичность двух разных списков ложна.',py(2))
exercise('COUNT и NULL','В заказах суммы 100 и NULL.','Сравните подсчёт строк и непустых сумм.', 'SELECT COUNT(*), COUNT(amount) FROM orders', 'COUNT(*) считает две строки. COUNT(amount) пропускает NULL и даёт один.',py(58),'sql')
exercise('LEFT JOIN без заказа','У Анны два заказа, у Бориса ни одного.','Выполните левое соединение вместо внутреннего.', 'SELECT u.name, o.id FROM users u LEFT JOIN orders o ON o.user_id=u.id ORDER BY u.id,o.id', 'LEFT JOIN сохраняет Бориса с NULL в столбце заказа; Анна появляется по одному разу на каждый заказ.',py(58),'sql')
exercise('Фильтр правой таблицы в WHERE','LEFT JOIN сохранял пользователя без заказа.','Добавили условие суммы в WHERE.', 'SELECT u.name, o.id FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE o.amount > 0 ORDER BY u.id,o.id', 'NULL > 0 не истинно. WHERE убирает строку Бориса и заказ с неизвестной суммой.',py(58),'sql')
exercise('Перенос условия в ON','Условие суммы в WHERE убрало пользователя без подходящего заказа.','Перенесли условие в ON левого соединения.', 'SELECT u.name, o.id FROM users u LEFT JOIN orders o ON o.user_id=u.id AND o.amount > 0 ORDER BY u.id,o.id', 'ON определяет подходящие пары. Для Бориса подходящих заказов нет, но LEFT JOIN сохраняет его строку.',py(58),'sql')
exercise('Правильная проверка NULL','Сравнение через = возвращает неизвестность для NULL.','Вместо = NULL используем IS NULL.', 'SELECT id FROM orders WHERE amount IS NULL ORDER BY id', 'IS NULL выбирает заказ с отсутствующей суммой.',py(58),'sql')
exercise('NULL в NOT IN','Выбираем пользователей без заказов.','В список сравнения случайно попал NULL. Будут ли строки?', 'SELECT name FROM users WHERE id NOT IN (1, NULL)', 'Для Бориса сравнение с NULL остаётся неизвестным, поэтому WHERE его не пропускает. Результат пуст; для такой задачи удобнее NOT EXISTS.',py(58),'sql')
exercise('NOT EXISTS вместо NOT IN','NULL в списке NOT IN испортил фильтр.','Проверяем отсутствие связанного заказа через NOT EXISTS.', 'SELECT name FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id=u.id) ORDER BY u.id', 'NOT EXISTS проверяет наличие подходящей строки, поэтому возвращается Борис.',py(58),'sql')
exercise('Дубликаты после JOIN','У одного пользователя несколько заказов.','Получите уникальные имена после соединения.', 'SELECT DISTINCT u.name FROM users u JOIN orders o ON o.user_id=u.id ORDER BY u.name', 'DISTINCT убирает повторяющиеся имена результата. Если разные пользователи могут иметь одно имя, это не способ подсчитать пользователей.',py(58),'sql')
def conceptual(title,base,change,answer,explanation,card):
 item=dict(id=f'whatif-{len(whatifs)+1:03}',title=title,base=base,change=change,code='',answer=answer,explanation=explanation,card_id=card,kind='case');item['audio']=track(title+'. Изменение условия. '+change+' Ответ. '+answer+' '+explanation,'whatif');whatifs.append(item)
conceptual('Worker стало четыре','Приложение хранило счётчик в обычной глобальной переменной.','Запустили четыре worker-процесса. Получится ли единый счётчик?','Нет: у каждого процесса своя память.','Для общего счётчика нужно внешнее согласованное хранилище с атомарными операциями. Увеличение числа worker само по себе не синхронизирует состояние.',py(101))
conceptual('Повтор платежа после тайм-аута','Клиент не дождался ответа платёжного API.','Клиент повторил запрос. Значит ли тайм-аут, что первый платёж не прошёл?','Нет: первый запрос мог выполниться, а ответ потеряться.','Нужны согласованный ключ идемпотентности, проверка состояния операции и правила повторов провайдера. Слепой повтор может создать второй платёж.',py(67))
conceptual('Падение после on_commit','Callback запланирован на успешный коммит.','Процесс упал сразу после коммита, до отправки сообщения. Гарантирует ли on_commit доставку?','Нет: callback не является надёжной очередью.','Для надёжной передачи намерение можно записать в outbox в той же транзакции; отдельный обработчик отправляет его с повторными попытками и идемпотентным потребителем.',py(55))
conceptual('Лишний await не спасает','Endpoint объявлен async def.','Внутри всё ещё вызывается time.sleep. Другие задачи этого event loop продолжат выполняться во время сна?','Нет: time.sleep блокирует поток цикла событий.','Для асинхронной паузы нужен await asyncio.sleep. Для блокирующего I/O применяют подходящий поток или асинхронную библиотеку; CPU-нагрузку рассматривают отдельно.',py(49))
comparisons=[]
def compare(title,left,right,choice,example,trap,question,answer,ids):
 body=title+'. Первое. '+left+' Второе. '+right+' Как выбрать. '+choice+' Ловушка. '+trap
 comparisons.append(dict(id=f'compare-{len(comparisons)+1:03}',title=title,left=left,right=right,choice=choice,example=example,trap=trap,question=question,answer=answer,card_ids=[py(n) if isinstance(n,int) else n for n in ids],audio=track(body,'compare')))
compare('is и ==','is проверяет идентичность: один ли это объект.','== проверяет равенство по правилам типа.','Для сравнения значений обычно нужен ==; для одиночного None используют is None.','a = [1]; b = [1]\nprint(a == b)  # True\nprint(a is b)  # False','Интернирование некоторых чисел и строк может маскировать ошибочное применение is.','Как сравнить два независимо полученных списка по содержимому?','Через ==. is ответит только на вопрос об идентичности объектов.',[2])
compare('shallow copy и deepcopy','Поверхностная копия создаёт новый внешний контейнер с прежними ссылками внутри.','Глубокая копия рекурсивно копирует вложенные объекты с учётом правил копирования.','Для независимых изменяемых вложенных данных может понадобиться deepcopy; иногда лучше явно построить нужные структуры.','from copy import deepcopy\na = [[1]]\nb = a.copy(); c = deepcopy(a)\nb[0].append(2)  # a изменился; c нет','Deepcopy не делает любой ресурс безопасно копируемым и может стоить дорого.','Достаточно ли a[:] для независимого списка списков?','Нет, вложенные списки останутся общими.',[27,28])
compare('iterable и iterator','Iterable позволяет получить итератор вызовом iter.','Iterator хранит текущее состояние и выдаёт элементы через next.','Список допускает новые независимые обходы; конкретный генератор обычно исчерпывается.','values = [1, 2]\nit = iter(values)\nprint(list(it)); print(list(it))','Нельзя считать, что любой переданный Iterable можно без последствий обойти дважды.','Что передать, если функции нужны два независимых прохода?','Повторно обходимую коллекцию, фабрику итераторов либо осознанно материализованные значения.',[23,25])
compare('asyncio, потоки и процессы','Asyncio переключает задачи в точках ожидания, потоки могут перекрывать блокирующее I/O.','Процессы имеют раздельную память и позволяют распределять CPU-работу между ядрами.','Выбор зависит от библиотек, нагрузки, версии и сборки Python; обычный asyncio не делает CPU-цикл параллельным.','await asyncio.sleep(1)  # уступает управление\n# Тяжёлый расчёт: отдельный процесс/воркер','GIL не защищает бизнес-инварианты; детали параллелизма зависят от сборки Python.','Для независимых тяжёлых расчётов выбрали бы только asyncio?','Обычно нет: рассмотреть процессы или отдельные вычислительные worker, затем измерить результат.',[45,46,49])
compare('INNER JOIN и LEFT JOIN','INNER JOIN оставляет подходящие пары строк.','LEFT JOIN также сохраняет строки левой таблицы без пары, дополняя правые колонки NULL.','LEFT JOIN нужен, если отсутствие связанной записи тоже важно для результата.','SELECT u.id, o.id FROM users u\nLEFT JOIN orders o ON o.user_id = u.id','Фильтр правой таблицы в WHERE может убрать строки без пары.','Как показать всех пользователей, включая тех, у кого нет заказов?','Использовать LEFT JOIN и внимательно разместить условия фильтрации.',[58])
compare('WHERE и HAVING','WHERE отбирает строки до группировки.','HAVING отбирает сформированные группы.','Фильтр статуса заказа — WHERE, условие по COUNT группы — HAVING.','SELECT user_id, COUNT(*) FROM orders\nWHERE status = \'paid\'\nGROUP BY user_id HAVING COUNT(*) >= 2','WHERE COUNT(*) > 1 на том же уровне запроса не заменяет HAVING.','Где проверить, что у пользователя минимум два оплаченных заказа?','Статус фильтровать в WHERE, число заказов группы — в HAVING.',[58,62])
compare('select_related и prefetch_related','select_related загружает связанные FK/OneToOne в SQL-соединении.','prefetch_related делает дополнительные запросы и соединяет результаты в Python; подходит и для множественных связей.','Выбирать по типу связи и фактическому числу строк/запросов.','Order.objects.select_related("customer")\nCustomer.objects.prefetch_related("orders")','Один запрос не всегда дешевле нескольких: учитывать размер результата и память.','Чем загрузить список заказов для каждого клиента?','Обычно prefetch_related для обратной множественной связи, с проверкой количества запросов.',[61,71])
compare('Аутентификация и авторизация','Аутентификация устанавливает, кто обращается.','Авторизация проверяет, разрешено ли этому субъекту конкретное действие над конкретным ресурсом.','После проверки токена всё равно проверять права и владельца объекта.','user = authenticate(token)\norder = load_order(order_id)\ncheck_access(user, order)','Действительный JWT не означает доступ ко всем объектам API.','Достаточно ли проверить подпись токена перед выдачей чужого заказа?','Нет. Нужна проверка доступа к самому заказу.',[84,85])
compare('Unit и интеграционный тест','Unit-тест проверяет небольшую единицу логики в изоляции.','Интеграционный тест проверяет совместную работу компонентов и реальные контракты.','Чистый расчёт удобно тестировать отдельно, SQL и транзакции — с подходящей настоящей БД.','assert calculate_total(items) == 100\n# Отдельно: запрос к тестовой БД и проверка ограничений','Mock БД не доказывает корректность SQL, блокировок или миграций.','Как проверить реальную уникальность при двух конкурентных записях?','Интеграционно с реальной БД и конкурентными операциями; чистого mock недостаточно.',[90,92,94])
compare('on_commit и transactional outbox','on_commit откладывает callback до успешного коммита.','Outbox сохраняет намерение отправить сообщение в той же транзакции, что и бизнес-изменение.','Если потеря сообщения недопустима, продумать outbox, доставку с повторами и идемпотентность.','# В одной транзакции:\n# update order\n# insert outbox event','Outbox сам по себе не даёт exactly-once обработку во внешней системе.','Что защищает от падения между коммитом заказа и отправкой события?','Запись outbox вместе с заказом и последующая надёжная обработка; одного callback недостаточно.',[55,'django-008'])
compare('BackgroundTasks и очередь worker','BackgroundTasks FastAPI выполняет работу в процессе приложения после ответа.','Внешняя очередь и worker позволяют отдельно организовать хранение задач, повторные попытки и масштабирование.','Короткую некритичную работу можно оставить в процессе; надёжные длительные задания требуют отдельного решения.','# Некритичный callback: BackgroundTasks\n# Надёжное задание: брокер + worker + идемпотентность','Наличие брокера не отменяет проектирование подтверждений, повторов и обработки дубликатов.','Куда отправить длительную генерацию отчёта, переживающую рестарт API?','В подходящую устойчивую очередь с worker и сохранённым состоянием задания.',[54,'fastapi-007'])
compare('revision, upgrade и stamp','revision создаёт файл миграции; autogenerate предлагает изменения для проверки.','upgrade выполняет миграции, stamp меняет только отметку ревизии.','Применять изменения схемы через upgrade; stamp допустим, когда соответствие схемы уже установлено отдельно.','alembic revision --autogenerate -m "add field"\nalembic upgrade head\n# stamp не выполняет upgrade()','Нельзя исправлять неизвестное расхождение схемы простым stamp head.','Нужно добавить колонку в БД. Достаточно ли stamp head?','Нет: stamp не выполняет операции миграции. Нужно проверить и применить корректную миграцию.', ['alembic-001','alembic-003','alembic-006'])
ids={c['id'] for c in cards}
assert len(whatifs)==24 and len(comparisons)==12
assert all(t['card_id'] in ids for t in whatifs)
